Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='contextbudget', at=datetime(2026, 11, 4, 0, 0, 0), actor='owner', title='Each unit is usable from 25k tokens and developable within 500k; the reading set only falls', body="Every unit of the repository (a crate, the web tree, an external library at its pin) is usable from its README plus its public interface in at most 25k tokens, and developable within 500k tokens: its own source, the documents it cites, and each dependency's use cost. The guard (app/cli/tests/guards/context.rs) enforces it and ratchets the repository's reading set downward. A unit too large is split into libraries, and a stable library moves to its own repository pinned by rev.", rationale='The owner, 2026-11-04: the codebase must be understandable by an agent that reads all of it; separate libraries may each need their own context, as long as each is easy to use and can be developed within the context.', supersedes=()))